import md from 'markdown-it'

import cites from './dist/index.js'

const engine = md().use(cites,{ 
  /*citeproc: () => ({
      appendCluster(cluster) {
          console.log(cluster)
      }
  })*/
})

console.log(engine.render("Hallo [@foo, p. 33] and so on"))
console.log(engine.render("Some studies [@foo; @bar, p. 33] bla blub @baz [chap. 1]"))
console.log(engine.render("Blah blah [see @doe99, pp. 33-35; also @smith04, chap. 1]."))
console.log(engine.render("Blah blah [@doe99, pp. 33-35, 38-39 and *passim*]."))
console.log(engine.render("Blah blah [@smith04; @doe99]."))
console.log(engine.render("[@smith{ii, A, D-Z}, with a suffix]"))
console.log(engine.render("[@smith, {pp. iv, vi-xi, (xv)-(xvii)} with suffix here]"))
console.log(engine.render("Smith says blah [-@smith04]."))
console.log(engine.render("@smith04 says blah."))
console.log(engine.render("@smith04 [p. 33] says blah."))